import { ChangeDetectionStrategy, Component, input } from '@angular/core'
import { IconName } from '@/core/models'

/**
 * A glyph of the icon font generated by fantasticon (src/assets/fonts/icons.*). The glyph scales to
 * the size given to the host (h-4 w-4, h-10 w-10…) and takes the text colour.
 */
@Component({
  selector: 'app-icon',
  template:
    '<i class="icon__glyph" [class]="\'icon__glyph icon-\' + name()"></i>',
  styleUrl: './icon.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { class: 'icon', 'aria-hidden': 'true' },
})
export class IconComponent {
  readonly name = input.required<IconName>()
}
